<?php
namespace App\Services;use App\Models\Invoice;use Illuminate\Support\Facades\Storage;
class InvoicePdfService{public function generate(Invoice $invoice):string{$b=$invoice->booking->loadMissing('facility');$lines=['SPORT CENTER','INVOICE '.$invoice->invoice_number,'Booking: '.$b->booking_number,'Customer: '.$b->customer_name,'Email: '.$b->customer_email,'Phone: '.$b->customer_phone,'Facility: '.$b->facility->name,'Date: '.$b->booking_date->format('d-m-Y'),'Time: '.substr($b->start_time,0,5).' - '.substr($b->end_time,0,5),'Duration: '.($b->duration_minutes/60).' jam','Payment: PAID','Total: Rp '.number_format($b->total,0,',','.'),'Paid at: '.optional($b->paid_at)->format('d-m-Y H:i')];$esc=fn($s)=>str_replace(['\\','(',')'],['\\\\','\\(','\\)'],(string)$s);$stream="BT /F1 12 Tf 50 800 Td ";foreach($lines as $i=>$line){if($i>0)$stream.="0 -24 Td ";$stream.="(".$esc($line).") Tj ";}$stream.="ET";$pdf="%PDF-1.4\n";$objs=[1,'<< /Type /Catalog /Pages 2 0 R >>',2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>',3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>',4,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',5,'<< /Length '.strlen($stream).' >>'."\nstream\n".$stream."\nendstream"];$off=[0];foreach(array_chunk($objs,2)as$o){$off[$o[0]]=strlen($pdf);$pdf.=$o[0]." 0 obj\n".$o[1]."\nendobj\n";}$xref=strlen($pdf);$pdf.="xref\n0 6\n0000000000 65535 f \n";for($i=1;$i<=5;$i++)$pdf.=sprintf('%010d 00000 n \n',$off[$i]);$pdf.="trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n".$xref."\n%%EOF";$path='invoices/'.$invoice->invoice_number.'.pdf';Storage::disk('local')->put($path,$pdf);return $path;}}
